	@Autowired
    private final TypeCertificateEntityProjector projector;
	private final TypeCertificateValidator validator;
	private TypeCertificate typeCertificate 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(TypeCertificateService.class);
